from pathlib import Path
import hashlib,json
from PIL import Image
P=Path('/tmp/cqc-pass19-gekko-generation')
def pin(path):
    path=Path(path);return {'path':str(path),'bytes':path.stat().st_size,'sha256':hashlib.sha256(path.read_bytes()).hexdigest()}
items=[
 ('trenchcoat-mgs4-left-parts-v1.png','exec-0e80ed23-daa8-485c-bb30-d9f10452230a.png','trenchcoat-mgs4-left-parts-v1.txt','rejected-complete-rig-retained-native-original'),
 ('trenchcoat-mgs4-left-parts-v2.png','exec-2ee9f19a-bb8c-472d-a694-d88a6b23adce.png','trenchcoat-mgs4-left-parts-v2.txt','selected-robot-spheres-hands-arm-legs-fedora; initial-vest-like-garment-replaced-by-V3'),
 ('gekko-suicide-mgs4-left-parts-v1.png','exec-04d4edfb-feab-4c73-be9c-0da33d1dc252.png','gekko-suicide-mgs4-left-parts-v1.txt','selected-dark-chassis-hip-blocks; rejected-chunky-leg-components-retained'),
 ('gekko-missile-mgs4-left-parts-v1.png','exec-990e9b5a-b05c-4409-8e99-5bb515a8fbe7.png','gekko-missile-mgs4-left-parts-v1.txt','selected-chassis-hip-blocks-missile-pod; rejected-chunky-leg-components-retained; hidden-projectile-unused'),
 ('gekko-mgr-left-parts-v1.png','exec-f7792a0c-a1ee-4d3b-8ffa-7426943f260f.png','gekko-mgr-left-parts-v1.txt','selected-camouflage-chassis-hip-blocks; rejected-chunky-leg-components-retained'),
 ('double-tripod-mgr-left-parts-v1.png','exec-1134356f-ac34-46ed-a134-01f851210c25.png','double-tripod-mgr-left-parts-v1.txt','selected-two-unit-articulated-original'),
 ('trenchcoat-garment-capped-shoulders-v3.png','exec-786406eb-a44d-4b44-b928-b62bf8c59315.png','trenchcoat-garment-capped-shoulders-v3.txt','selected-new-native-covered-shoulders-long-sleeves-coat'),
 ('gekko-common-original-organic-calves-hooves-v1.png','exec-f1f42947-96fb-4d77-b6bf-ac692c232489.png','gekko-common-original-organic-calves-hooves-v1.txt','selected-source-led-long-biological-calves-and-ankle-only-hooves')
]
generations=[]
for name,tool,prompt,status in items:
    native=pin(P/'native-originals'/name);original=pin(Path('/workspace/generated_images')/tool);assert native['sha256']==original['sha256'] and native['bytes']==original['bytes'];im=Image.open(native['path'])
    generations.append({'native':native,'toolOriginal':original,'prompt':pin(P/'prompts'/prompt),'width':im.width,'height':im.height,'mode':im.mode,'selectionStatus':status,'pixelsEdited':False,'absolute1to1Certified':False})
(P/'NATIVE_GENERATIONS_WITH_PROMPT_PINS_ACTUAL_V1.json').write_text(json.dumps({'schema':'cqc.pass19.native-generation-preservation/1','nativeTool':'image_gen.imagegen','generations':generations,'preparedButNotExecutedPrompts':['gekko-suicide-mgs4-left-parts-v2-alpha.txt','raptor-mgr-left-parts-v1.txt'],'nativeOriginalsRetained':True,'toolOriginalsRetained':True,'pixelEditingPerformed':False},indent=2)+'\n')
cat=json.loads((P/'NEW_PLAYABLE_NATIVE_RIGS_V1.json').read_text());selected={}
for m in cat['machines']:
    for s in m['sources']:
        actual=pin(P/'runtime'/s['file']);assert actual['sha256']==s['sha256'] and actual['bytes']==s['bytes'];native=pin(P/'native-originals'/Path(s['file']).name);assert actual['sha256']==native['sha256'];selected[s['file']]=actual
runtimeCode=[pin(P/'runtime/src'/f) for f in ['cqc-pass19-gekko-catalog.js','cqc-pass19-gekko-poses.js','cqc-machine-parts-renderer-v1.js']]
qa=json.loads((P/'qa/ASSEMBLED_ACTUAL_BROWSER_QA_V7.json').read_text());comparison=json.loads((P/'qa/REFERENCE_VS_ASSEMBLED_ACTUAL_BROWSER_QA_V7.json').read_text());assert qa['status']=='passed' and comparison['status']=='passed'
for report in [qa,comparison]:
    for s in report['screenshots']:assert pin(s['path'])['sha256']==s['sha256']
delivery={'schema':'cqc.pass19.gekko-native-playable-delivery/1','readyForRootVisualReview':True,'rootVisualAcceptancePending':True,'localOnlyNotProduction':True,'catalog':pin(P/'NEW_PLAYABLE_NATIVE_RIGS_V1.json'),'presentationMaps':pin(P/'PLAYABLE_PRESENTATION_MAPS_V1.json'),'runtimeCode':runtimeCode,'nativePreservationLedger':pin(P/'NATIVE_GENERATIONS_WITH_PROMPT_PINS_ACTUAL_V1.json'),'selectedRuntimeNativeSources':list(selected.values()),'generatedOriginalCount':len(generations),'selectedUniquePNGCount':len(selected),'rigCount':len(cat['machines']),'rigPartCount':sum(len(m['parts']) for m in cat['machines']),'rootOwnedIntegration':{'globalCatalog':'CQC_PASS19_GEKKO_CATALOG','globalPresentationMaps':'CQC_PASS19_GEKKO_DATA','actionPoseAPI':'CQC_PASS19_GEKKO_POSES.pose(uid,{action,frame,phaseProgress,flags,channels,reducedMotion,coatOpened})','nativeRenderer':'CQC_MACHINE_PARTS.create / normalizeCatalog / draw','sourceBasePath':'assets/machines-pass19/','combatHPAndColliderOwnedByRoot':True,'worldScaleOwnedByRoot':True},'visualReviews':[pin(P/'qa/ASSEMBLED_ACTUAL_BROWSER_QA_V7.json'),pin(P/'qa/REFERENCE_VS_ASSEMBLED_ACTUAL_BROWSER_QA_V7.json')],'actualScreenshotCount':len(qa['screenshots'])+len(comparison['screenshots']),'qualifications':['All PNG originals, rejects and selected pixels are preserved exactly. Only uniform positive Canvas scale, crop/clip, joint rotation and translated offsets used.','Coat native garment V3 corrects initial uncovered shoulders; closed silhouette hides all three robots under coat/fedora and keeps mechanical hands/hand-feet.','Double Tripod has exactly two spheres and all six robot arms represented, including lower vertical link and upper stowed third arm.','Three Gekko rigs now render authentic mechanical hip/femur blocks, one long black biological calf per leg and silver ankle-only hooves. Old chunky organic-thigh sources retained and not selected.','Only left-native oblique source currently exists. Same untouched native image for opposite presentation is qualified projection; independent reverse-facing source remains outstanding.','Absolute1to1Certified remains false; hidden joints, perspective, material interpretation and 2D gameplay adaptation are not certified canon geometry.','No exact physical grenade-launcher mount or carrier arrangement established; these two UIDs remain ungenerated/inactive.','Optional six UG generation suspended by root to prioritize reviewed playable Gekko rigs. Physical original Raptor/Vodomjerka concepts and partial Mastiff gameplay references exist; final Fenrir,Slider,Hammerhead still need dedicated physical verification.']}
(P/'GEKKO_PLAYABLE_DELIVERY_PINNED_ACTUAL_V1.json').write_text(json.dumps(delivery,indent=2)+'\n')
print(json.dumps({'delivery':pin(P/'GEKKO_PLAYABLE_DELIVERY_PINNED_ACTUAL_V1.json'),'catalogSHA256':delivery['catalog']['sha256'],'runtimeCode':runtimeCode,'rigCount':delivery['rigCount'],'parts':delivery['rigPartCount'],'nativeSources':delivery['selectedUniquePNGCount'],'generatedOriginals':delivery['generatedOriginalCount'],'actualScreenshots':delivery['actualScreenshotCount']}))
